	for _, tt := range tests {
		body, ok := sections[tt.section]
		if !ok {
			t.Fatalf("help has no %q section", tt.section)
		}
		if !strings.Contains(body, tt.want) {
			t.Errorf("section %q does not say %q:\n%s", tt.section, tt.want, body)
		}
	}
}
